service.method:

DELETE 
  FROM #DB_OWNER#SCODE 
 WHERE TYPE       = ${MODULE_TYPE} 
   AND CODE       = ${TYPE} 
   AND HOUSE_CODE = ${session.HOUSE_CODE}


DELETE 
  FROM #DB_OWNER#SCODE 
 WHERE TYPE       = ${TYPE}
   AND CODE       = ${CODE}
   AND HOUSE_CODE = ${session.HOUSE_CODE}


SELECT COUNT(*) CNT
  FROM SCODE
 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
   AND LANGUAGE   = ${LANGUAGE}
   AND TYPE       = ${MODULE_TYPE}
   AND CODE       = ${TYPE}


SELECT COUNT(*) CNT
  FROM SCODE
 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
   AND LANGUAGE   = ${LANGUAGE}
   AND TYPE       = ${TYPE}
   AND CODE       = ${CODE}


		INSERT 
		  INTO #DB_OWNER#SCODE
	         ( HOUSE_CODE
	         , TYPE
	         , CODE
	         , LANGUAGE
	         , ADD_DATE
	         , ADD_TIME
	         , ADD_USER_ID
	         , CHANGE_DATE
	         , CHANGE_TIME
	         , CHANGE_USER_ID
	         , FLAG
	         , SORT_SEQ
	         , USE_FLAG
	         , TEXT1
	         , TEXT2
	         , TEXT3
	         , TEXT4
	         , TEXT5
	         , TEXT6
	         , TEXT7
	         , TEXT8
	         , DEL_FLAG  
             , CLIENT_CUSTOM_FLAG
	         )
	   VALUES( 
	           ${session.HOUSE_CODE}
	         , ${MODULE_TYPE}
	         , ${TYPE}
	         , ${LANGUAGE}
	         , ${current.DATE}
	         , ${current.TIME}
	         , ${session.ID}
	         , ${current.DATE}
	         , ${current.TIME}
	         , ${session.ID}
	         , ${FLAG}
	         , #{SORT}
	         , CASE WHEN ${USE_FLAG} = 'N' THEN 'N' ELSE 'Y' END
	         , ${TEXT1}
	         , ${TEXT2}
	         , ${TEXT3}
	         , ${TEXT4}
	         , ${TEXT5}
	         , ${TEXT6}
	         , ${TEXT7}
	         , ${TEXT8}
	         , 'N'
             , ${CLIENT_CUSTOM_FLAG}  
	       )


		UPDATE #DB_OWNER#SCODE
		   SET CHANGE_DATE    = ${current.DATE}
	         , CHANGE_TIME    = ${current.TIME}
	         , CHANGE_USER_ID = ${session.ID}
	         , FLAG           = ${FLAG}
	         , SORT_SEQ       = #{SORT}
	         , USE_FLAG       = CASE WHEN ${USE_FLAG} = 'N' THEN 'N' ELSE 'Y' END 
	         , TEXT1          = ${TEXT1}
	         , TEXT2          = ${TEXT2}
	         , TEXT3          = ${TEXT3}
	         , TEXT4          = ${TEXT4}
	         , TEXT5          = ${TEXT5}
	         , TEXT6          = ${TEXT6}
	         , TEXT7          = ${TEXT7}
	         , TEXT8          = ${TEXT8}
	         , DEL_FLAG       = 'N'
             , CLIENT_CUSTOM_FLAG = ${CLIENT_CUSTOM_FLAG}
	     WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	       AND LANGUAGE   = ${LANGUAGE}
	       AND TYPE       = ${MODULE_TYPE}
	       AND CODE       = ${TYPE}


	INSERT 
	  INTO #DB_OWNER#SCODE
         ( HOUSE_CODE
         , TYPE
         , CODE
         , LANGUAGE
         , ADD_DATE
         , ADD_TIME
         , ADD_USER_ID
         , CHANGE_DATE
         , CHANGE_TIME
         , CHANGE_USER_ID
         , FLAG
         , SORT_SEQ
         , USE_FLAG
         , TEXT1
         , TEXT2
         , TEXT3
         , TEXT4
         , TEXT5
         , TEXT6
         , TEXT7
         , TEXT8
         , DEL_FLAG  
         )
   VALUES( 
           ${session.HOUSE_CODE}
         , ${TYPE}
         , ${CODE}
         , ${LANGUAGE}
         , ${current.DATE}
         , ${current.TIME}
         , ${session.ID}
         , ${current.DATE}
         , ${current.TIME}
         , ${session.ID}
         , ${FLAG}
         , #{SORT}
         , CASE WHEN ${USE_FLAG}= '1' THEN 'Y' ELSE 'N' END
         , ${TEXT1}
         , ${TEXT2}
         , ${TEXT3}
         , ${TEXT4}
         , ${TEXT5}
         , ${TEXT6}
         , ${TEXT7}
         , ${TEXT8}
         , 'N'  
       )


	UPDATE #DB_OWNER#SCODE
	   SET CHANGE_DATE    = ${current.DATE}
         , CHANGE_TIME    = ${current.TIME}
         , CHANGE_USER_ID = ${session.ID}
         , FLAG           = ${FLAG}
         , SORT_SEQ       = #{SORT}
         , USE_FLAG       = CASE WHEN ${USE_FLAG}= '1' THEN 'Y' ELSE 'N' END
         , TEXT1          = ${TEXT1}
         , TEXT2          = ${TEXT2}
         , TEXT3          = ${TEXT3}
         , TEXT4          = ${TEXT4}
         , TEXT5          = ${TEXT5}
         , TEXT6          = ${TEXT6}
         , TEXT7          = ${TEXT7}
         , TEXT8          = ${TEXT8}
         , DEL_FLAG       = 'N'
     WHERE HOUSE_CODE = ${session.HOUSE_CODE}
       AND LANGUAGE   = ${LANGUAGE}
       AND TYPE       = ${TYPE}
       AND CODE       = ${CODE}
